-- Mutation fixture: its own synthetic customer, restored by the enclosing rollback.
create function pg_temp.mid(n integer) returns uuid language sql immutable as $$select ('44005000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into public.customers(id,name) values(pg_temp.mid(1),'Syntetiskt ändringsprov');
insert into public.organizers(id,customer_id,name,type) values(pg_temp.mid(2),pg_temp.mid(1),'Syntetiskt ändringsprov','Kommun');
insert into public.identities(id,issuer,subject) select pg_temp.mid(n),'https://mutation.example.test',n::text from generate_series(10,13)n;
insert into public.memberships(id,identity_id,customer_id) select pg_temp.mid(n+10),pg_temp.mid(n),pg_temp.mid(1) from generate_series(10,13)n;
insert into public.school_units(id,organizer_id,code,name,municipality_code) select pg_temp.mid(n),pg_temp.mid(2),'440050'||n,'Provskola '||n,'0180' from generate_series(30,32)n;
insert into public.offerings(id,organizer_id,unit_id,kind,name,cohort,start_year) select pg_temp.mid(n+10),pg_temp.mid(2),pg_temp.mid(n),'grundskola','Provutbildning','Provkull',2026 from generate_series(30,32)n;
insert into public.offerings(id,organizer_id,unit_id,kind,name,cohort,start_year) values(pg_temp.mid(43),pg_temp.mid(2),pg_temp.mid(30),'grundskola','Annan utbildning','Provkull',2026);
insert into public.school_classes(id,customer_id,organizer_id,unit_id,offering_id,name,start_year) select pg_temp.mid(n+20),pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(n),pg_temp.mid(n+10),'PROV'||n,2026 from generate_series(30,32)n;
insert into public.school_classes(id,customer_id,organizer_id,unit_id,offering_id,name,start_year) values(pg_temp.mid(53),pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(30),pg_temp.mid(43),'ANNAN',2026);
insert into public.access_assignments(id,membership_id,customer_id,organizer_id,function,profile_id,scope_kind) values(pg_temp.mid(60),pg_temp.mid(20),pg_temp.mid(1),pg_temp.mid(2),'huvudman','synthetic-v1','school');
insert into public.mandate_units select pg_temp.mid(60),pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(n) from generate_series(30,32)n;
create temp table mutation_roles(name text primary key,id uuid);
create function pg_temp.ma(name text) returns void language plpgsql as $$declare a public.access_assignments; begin
select * into a from public.access_assignments where id=case when name='hm' then pg_temp.mid(60) else (select r.id from mutation_roles r where r.name=ma.name) end;
perform set_config('app.customer_id',a.customer_id::text,true),set_config('app.assignment_id',a.id::text,true),set_config('app.membership_id',a.membership_id::text,true),set_config('app.identity_id',(select identity_id::text from public.memberships where id=a.membership_id),true); end$$;
select pg_temp.ma('hm');
insert into mutation_roles values('principal',public.phase3_grant_mandate(jsonb_build_object('membershipId',pg_temp.mid(21),'function','rektor','scopeKind','school','unitIds',jsonb_build_array(pg_temp.mid(30),pg_temp.mid(31),pg_temp.mid(32)))));
select pg_temp.ma('principal');
insert into mutation_roles select label,public.phase3_grant_mandate(jsonb_build_object('membershipId',member,'function','administrator','scopeKind','school','unitIds',jsonb_build_array(pg_temp.mid(30),pg_temp.mid(31)))) from (values('admin',pg_temp.mid(22)),('admin2',pg_temp.mid(23)))r(label,member);
insert into public.pupils(id,customer_id,organizer_id,display_name,personal_number,anonymous_name) values(pg_temp.mid(70),pg_temp.mid(1),pg_temp.mid(2),'Syntetisk elev','TEST-20100101-0014','Elev prov');
insert into public.pupil_placements(id,customer_id,organizer_id,pupil_id,unit_id,offering_id,starts_on) values(pg_temp.mid(80),pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(70),pg_temp.mid(30),pg_temp.mid(40),public.app_today()-100);
insert into public.pupil_class_memberships(id,customer_id,organizer_id,pupil_id,unit_id,class_id,placement_id,starts_on) values(pg_temp.mid(90),pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(70),pg_temp.mid(30),pg_temp.mid(50),pg_temp.mid(80),public.app_today()-100);
insert into public.pupil_home_municipalities(id,customer_id,organizer_id,pupil_id,municipality_code,starts_on) values(pg_temp.mid(100),pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(70),'0180',public.app_today()-100);
create function pg_temp.mreq(kind text,payload jsonb,v integer default null) returns jsonb language sql as $$select jsonb_build_object('pupilId',pg_temp.mid(70),'schoolYear',extract(year from public.app_today())::integer-case when extract(month from public.app_today())<7 then 1 else 0 end,'caseId',null,'expectedVersion',coalesce(v,(select version from public.pupils where id=pg_temp.mid(70))),'kind',kind,'payload',payload)$$;
select pg_temp.ma('admin');

select has_function('public','phase4_simulated_source_deliver',array['jsonb'],'controlled source delivery exists');
select has_function('public','phase4_resolve_source',array['jsonb'],'explicit resolution exists');
create function pg_temp.deliver(field text,value jsonb) returns jsonb language sql as $$select public.phase4_simulated_source_deliver(jsonb_build_object('pupilId',pg_temp.mid(70),'field',field,'value',value))$$;
create function pg_temp.decide(choice text,v integer default null) returns jsonb language sql as $$select public.phase4_resolve_source(pg_temp.mreq('resolve-source',jsonb_build_object('conflictId',(select id from public.pupil_source_values where pupil_id=pg_temp.mid(70) and resolved_at is null order by changed_at desc limit 1),'choice',choice),v))$$;
select is(pg_temp.deliver('displayName','"Källnamn"')->>'status','conflict','different source creates pending conflict');
select is((select display_name from public.pupils where id=pg_temp.mid(70)),'Syntetisk elev','local effective value survives delivery');
select is((select local_value from public.pupil_field_state where pupil_id=pg_temp.mid(70)),'"Syntetisk elev"'::jsonb,'local correction stored separately');
select is((select latest_source_value from public.pupil_field_state where pupil_id=pg_temp.mid(70)),'"Källnamn"'::jsonb,'latest source stored separately');
select ok((select actor_id is null from public.pupil_source_values where pupil_id=pg_temp.mid(70)),'delivery does not impersonate staff');
select is(pg_temp.deliver('displayName','"Källnamn"')->>'status','unchanged','same delivery is idempotent');
select is((select version from public.pupils where id=pg_temp.mid(70)),2,'repeated delivery does not advance version');
select is((select count(*) from public.pupil_source_values where pupil_id=pg_temp.mid(70)),1::bigint,'no duplicate pending conflict');
select is(pg_temp.decide('local',1)->>'kind','conflict','stale decision requires reread');
select is(pg_temp.decide('local')->>'kind','success','explicit keep local succeeds');
select is((select resolution from public.pupil_field_history where pupil_id=pg_temp.mid(70) order by revision desc limit 1),'local','decision retained in history');
select ok(exists(select 1 from jsonb_array_elements(public.phase4_pupil_history((pg_temp.mreq('basics','{}')-'kind'-'payload'-'expectedVersion')||'{"page":1}')->'body'->'entries')e where e->>'resolution'='local'),'history projection exposes explicit local decision');
select is(pg_temp.deliver('displayName','"Källnamn"')->>'status','unchanged','repeated delivery cannot reopen resolved decision');
select is(public.phase4_change_pupil(pg_temp.mreq('basics','{"displayName":"Ny lokal rättelse"}'))->>'kind','success','explicit local correction remains editable');
select is((select local_value from public.pupil_field_state where pupil_id=pg_temp.mid(70)),'"Ny lokal rättelse"'::jsonb,'edited correction stays synchronized');
select is(pg_temp.deliver('displayName','"Källnamn två"')->>'status','conflict','new source creates new deviation');
select is(pg_temp.deliver('displayName','"Källnamn tre"')->>'status','conflict','updated source revises pending deviation');
select is((select count(*) from public.pupil_source_values where pupil_id=pg_temp.mid(70) and resolved_at is null),1::bigint,'updated source keeps one pending conflict');
select is(pg_temp.decide('source')->>'kind','success','explicit source choice succeeds');
select is((select display_name from public.pupils where id=pg_temp.mid(70)),'Källnamn tre','source choice uses latest delivery');
select throws_ok($q$select public.phase4_change_pupil(pg_temp.mreq('basics','{"displayName":"Nekad"}'))$q$,'42501',null,'source-owned basic field rejects direct edit');
select is((select writer_source from public.pupil_field_state where pupil_id=pg_temp.mid(70)),'simulated','source ownership retained');
select is(pg_temp.deliver('displayName','"Nästa källvärde"')->>'status','matched','source-owned field follows next source delivery');
select is((select display_name from public.pupils where id=pg_temp.mid(70)),'Nästa källvärde','refresh applies without fabricated local correction');
select is(pg_temp.deliver('personalNumber','"TEST-20100101-0022"')->>'status','conflict','number delivery creates deviation');
select ok(public.phase4_pupil_card(pg_temp.mreq('basics','{}')-'kind'-'payload'-'expectedVersion')::text not like '%TEST-%','card deviation never contains number');
select ok(public.phase4_pupil_history((pg_temp.mreq('basics','{}')-'kind'-'payload'-'expectedVersion')||'{"page":1}')::text not like '%TEST-%','history never contains number');
update public.memberships set status='blocked',blocked_at=clock_timestamp() where id=pg_temp.mid(22);
select throws_ok($q$select pg_temp.decide('source')$q$,'42501',null,'blocked membership cannot decide');
update public.memberships set status='active',blocked_at=null where id=pg_temp.mid(22);
update public.pupils set protected_identity=true where id=pg_temp.mid(70);
select throws_ok($q$select pg_temp.decide('source')$q$,'P0002',null,'protection checked before resolution');
update public.pupils set protected_identity=false where id=pg_temp.mid(70);
select pg_temp.ma('principal');
select throws_ok($q$select pg_temp.decide('source')$q$,'42501',null,'principal cannot mutate pupil source choice');
select pg_temp.ma('admin');
select throws_ok($q$select pg_temp.deliver('personalNumber','"191001010000"')$q$,'22023',null,'non-synthetic identity refused');
select throws_ok($q$select public.phase4_simulated_source_deliver(jsonb_build_object('pupilId',pg_temp.mid(70),'field','displayName','value','Name','actorId',pg_temp.mid(22)))$q$,'22023',null,'source caller cannot spoof actor');
select ok(not has_function_privilege(r,'public.phase4_simulated_source_deliver(jsonb)','execute'),'delivery denied for '||r) from unnest(array['anon','authenticated','skolplattform_worker'])r;
select ok(not has_function_privilege(r,'public.phase4_resolve_source(jsonb)','execute'),'resolution remains closed for '||r) from unnest(array['anon','authenticated','skolplattform_worker'])r;
select ok(not exists(select 1 from public.security_events where customer_id=pg_temp.mid(1) and action='pupil.source.deliver' and (actor_identity_id is not null or membership_id is not null or details::text like '%Källnamn%' or details::text like '%TEST-%')),'source log has no values or forged actor');
create function pg_temp.reject_source_audit() returns trigger language plpgsql as $$begin if new.action='pupil.source.deliver' then raise exception 'test audit unavailable' using errcode='55000'; end if; return new; end$$;
create trigger test_reject_source_audit before insert on public.security_events for each row execute function pg_temp.reject_source_audit();
create temp table before_audit_fail as select version,(select count(*) from public.pupil_field_history where pupil_id=pg_temp.mid(70)) as history_count from public.pupils where id=pg_temp.mid(70);
select throws_ok($q$select pg_temp.deliver('displayName','"Ej sparat"')$q$,'55000',null,'audit failure rejects delivery');
select is((select version from public.pupils where id=pg_temp.mid(70)),(select version from before_audit_fail),'audit failure rolls back version');
select is((select count(*) from public.pupil_field_history where pupil_id=pg_temp.mid(70)),(select history_count from before_audit_fail),'audit failure rolls back history');
select ok(not exists(select 1 from public.pupil_source_values where pupil_id=pg_temp.mid(70) and source_value='"Ej sparat"'),'audit failure rolls back conflict');
drop trigger test_reject_source_audit on public.security_events;
set local role anon;
select throws_ok($q$select public.phase4_simulated_source_deliver('{}')$q$,'42501',null,'anon cannot execute delivery');
reset role;
set local role authenticated;
select throws_ok($q$select public.phase4_simulated_source_deliver('{}')$q$,'42501',null,'authenticated cannot execute delivery');
reset role;
set local role skolplattform_worker;
select throws_ok($q$select public.phase4_simulated_source_deliver('{}')$q$,'42501',null,'worker cannot execute delivery');
reset role;
update public.pupil_class_memberships set ends_on=public.app_today()-1 where pupil_id=pg_temp.mid(70);
update public.pupil_placements set ends_on=public.app_today()-1 where pupil_id=pg_temp.mid(70);
select throws_ok($q$select pg_temp.decide('local')$q$,'P0002',null,'history-only pupil cannot resolve local');
select throws_ok($q$select pg_temp.decide('source')$q$,'P0002',null,'history-only pupil cannot resolve source');
select * from finish();
rollback;
